INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9305-chem324', 'stk-user9305', 'CHEM 324', 'doc', '{"docs": [{"id": "stk-dr-f68457", "n": "Dr. A. Kawde", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 324 (Advanced Analytical Chemistry) - Term 152 Lec & Lab\n\nالتحضير:\nيحضر بالنظر، كنا 8 طلاب فقط وأغلبنا يعرفه من كورسات سابقة.\n\nطريقة الشرح:\nيشرح من سلايدات وفاهم للمادة بشكل كبير.\n\nالكويزات:\nمتوسطة المستوى مائلة إلى الصعوبة.\n\nالمياجر:\n- كتابيات، هذي المادة تشابه 323 في كثير من المواضيع وطريقة الدراسة، كان الدكتور يحرص على وضع أسئلة رسم، مثل ارسم Plasma Torch و ارسم الرسم البياني اللي ممكن يطلع لك بعد إجرائك لتحليل باستخدام الـ HPLC وارسم FID Detector إلى آخره.\n\nالفاينل:\nكتابي في أغلبه وكان مليان رسم بشكل استثنائي، تقريباً 60% من الأسئلة كانت رسم…\n\nالصوت:\nواضح جداً.\n\nالمختبر:\nيشرح التجربة بوضوح، ويعطيك المانيوال، ويجيب على كل الأسئلة بصدر رحب وما يتململ من كثرتهن ابداً، إذا خلصت التجربة بإمكانك تسلم الريبورت وتمشي.\n\nإضافات:\n- حبيب جداً ومبتسم وطيب القلب.\n\n- أنصح به في 323 في المحاضرة و المختبر جميعاً.\n\n- أنصح به في أي مختبر لأي كورس.\n\nالقريد النهائي:\nA", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1451567-chem324", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-kawde/68457/15", "user": "user9305", "ts": 1465737996000, "tid": 68457, "pn": 15}}]}', 1465737996000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
